using System.Text.Json;
using System.Text;
var checks=new List<string>();void Check(bool ok,string label){if(!ok)throw new Exception(label);checks.Add(label);Console.WriteLine("PASS "+label);}async Task Denied(Func<Task> action,string label){try{await action();throw new Exception("Expected denial");}catch(Exception e)when(e is SimRfqIntakeProblem or LibraryBomPermissionException){Check(true,label);}}
var admin=SimPersonaCatalog.Default;var f=await Fixture.Create();var lanes=new Dictionary<string,SimRfqLanes>();
async Task Complete(int index){var record=SimRfqIntakeStore.BuildLibraryRfqRecord(f.Receipts[index],f.Packages[index]);var inputs=record.TechnicalReview!.Workflow!.Outputs!;var accepted=inputs.Materials;var quantity=record.Assemblies[0].Quantity;var rows=accepted.Candidate.Rows.Select(s=>SimRfqIntakeStore.DefaultMaterialQuantity(SimRfqIntakeStore.MaterialIdentityDefaults(new(s.Index,Vendor:"Mouser",UnitPrice:1,LeadDays:7),s),s,quantity)).ToArray();var calculated=rows.Select(r=>SimRfqIntakeStore.CalculateMaterial(r,accepted.Candidate.Rows.Single(s=>s.Index==r.Index),quantity)).ToArray();var total=calculated.Sum(r=>r.ExtendedCost??0);var snapshot=new SimMaterialSnapshot(1,accepted.Version,accepted.Candidate.Id,quantity,calculated,total,"USD","QA",f.Actor.AtUtc,0,total/quantity);var material=new SimMaterialPlan(1,accepted.Version,accepted.Candidate.Id,rows,"QA",f.Actor.AtUtc,[snapshot],0);var totals=new SimLaborTotals(0,50,50,50m/60,50,150,3);var laborSnapshot=new SimLaborSnapshot(1,inputs.Manufacturing.Id,quantity,[],60,0,totals,"QA",f.Actor.AtUtc,ManufacturingLead:new(2,"DAYS"));var labor=new SimLaborPlan(1,inputs.Manufacturing.Id,quantity,"QA",[],60,0,"QA",f.Actor.AtUtc,[laborSnapshot],ManufacturingLead:new(2,"DAYS"));lanes[record.IntakeId]=new(new("COMPLETE","QA",f.Actor.AtUtc),new("COMPLETE","QA",f.Actor.AtUtc),material,labor);await File.WriteAllTextAsync(Path.Combine(f.Root,"data/rfq-lanes.json"),JsonSerializer.Serialize(lanes,Fixture.Json));}
await Complete(0);var source=await f.Store.ReadEstimateSubmission(f.Id,admin);Check(source.CanSubmit&&source.Blockers.Length==0&&source.Revision==0,"Eligible .1 can submit independently while .2/.3 are not started");
foreach(var name in new[]{"ray","michelle","adan"})await Denied(()=>f.Store.SubmitEstimate(f.Id,new(Guid.NewGuid().ToString(),source.Revision,source.Token,source.EstimateId!),SimPersonaCatalog.Get(name)!),name+" gains no internal approval/submission authority");
Check((await f.Store.ReadEstimateSubmission(f.Id,SimPersonaCatalog.Get("miguel-jr")!)).CanSubmit,"Miguel Jr. retains existing authorized reviewer boundary");
var command=new SimEstimateSubmitRequest(Guid.NewGuid().ToString(),source.Revision,source.Token,source.EstimateId!);var beforeSource=f.FullStateHash();await Denied(()=>f.Store.SubmitEstimate(f.Id,command with{ExpectedToken="stale"},admin),"Stale token denied before writing");Check(f.FullStateHash()==beforeSource,"Denied stale submission leaves all fixture state unchanged");
var done=await f.Store.SubmitEstimate(f.Id,command,admin);Check(done.Current&&!done.CanSubmit&&done.History.Length==1&&!done.CustomerIssued,"Internal .1 receipt pins exact completed pair, not customer issuance");Check(done.History[0].Pair.MaterialsVersion==1&&done.History[0].Pair.LaborVersion==1&&done.History[0].Pair.Binding==f.Receipts[0].Binding,"Receipt pins exact package, quantity and component versions");
var repeat=await f.Store.SubmitEstimate(f.Id,command,admin);Check(repeat.History.Length==1,"Same request retry idempotently returns one internal receipt");await Denied(()=>f.Store.SubmitEstimate(f.Id,command with{RequestId=Guid.NewGuid().ToString()},admin),"New duplicate action cannot multiply submission receipts");
var queue=JsonSerializer.SerializeToElement(await f.Store.ReadRfqCommercialQueue(),Fixture.Json);var parent=queue.GetProperty("parentGroups").EnumerateArray().Single();Check(parent.GetProperty("totalLines").GetInt32()==3&&parent.GetProperty("submittedLines").GetInt32()==1&&parent.GetProperty("status").GetString()=="PARTIALLY_SUBMITTED_INTERNAL","Parent truthfully shows 1 of 3 internal submissions without changing parent Intake state");
var disk=JsonSerializer.Deserialize<Dictionary<string,SimRfqLanes>>(await File.ReadAllTextAsync(Path.Combine(f.Root,"data/rfq-lanes.json")),Fixture.Json)!;Check(disk.Count==1&&disk[f.Id].Commercial is null&&disk[f.Id].FinalReviews is null,"No sibling writes, commercial commitment or quotation approval is invented");
await Denied(()=>f.Store.TransitionRfqCommercial(f.Id,new(Guid.NewGuid().ToString(),0,"SUBMIT"),admin),"Existing customer commercial-submission gate remains blocked");
await Complete(1);lanes[f.Id]=disk[f.Id];await File.WriteAllTextAsync(Path.Combine(f.Root,"data/rfq-lanes.json"),JsonSerializer.Serialize(lanes,Fixture.Json));var second=await f.Store.ReadEstimateSubmission(f.SiblingId,admin);await f.Store.SubmitEstimate(f.SiblingId,new(Guid.NewGuid().ToString(),0,second.Token,second.EstimateId!),admin);var two=JsonSerializer.SerializeToElement(await f.Store.ReadRfqCommercialQueue(),Fixture.Json).GetProperty("parentGroups")[0];Check(two.GetProperty("submittedLines").GetInt32()==2,"Second line advances independently to 2 of 3");
disk=JsonSerializer.Deserialize<Dictionary<string,SimRfqLanes>>(await File.ReadAllTextAsync(Path.Combine(f.Root,"data/rfq-lanes.json")),Fixture.Json)!;await Complete(2);foreach(var pair in disk)lanes[pair.Key]=pair.Value;await File.WriteAllTextAsync(Path.Combine(f.Root,"data/rfq-lanes.json"),JsonSerializer.Serialize(lanes,Fixture.Json));var third=await f.Store.ReadEstimateSubmission(Fixture.ParentId+".3",admin);await f.Store.SubmitEstimate(Fixture.ParentId+".3",new(Guid.NewGuid().ToString(),0,third.Token,third.EstimateId!),admin);var all=JsonSerializer.SerializeToElement(await f.Store.ReadRfqCommercialQueue(),Fixture.Json).GetProperty("parentGroups")[0];Check(all.GetProperty("submittedLines").GetInt32()==3&&all.GetProperty("status").GetString()=="ALL_ESTIMATES_SUBMITTED_INTERNAL","Full aggregate only when all independent lines submit eligible current estimates");
var material=await f.Store.ReadMaterials(f.Id);var original=JsonSerializer.Serialize(done.History[0].Pair,Fixture.Json);await f.Store.SaveMaterials(f.Id,new(material.Plan.Revision,material.Plan.Rows.Select(r=>r.Index==0?r with{MfgPartNumber="UNAPPROVED-PROPOSAL",MfgPartNumberSource="MANUAL_QUOTE_ONLY",PartReviewMode="PROPOSED_PART"}:r).ToArray(),ChargeContractVersion:2,EvidenceContractVersion:1,PartReviewContractVersion:1),admin);var changed=await f.Store.ReadEstimateSubmission(f.Id,admin);Check(!changed.Current&&!changed.CanSubmit&&changed.Blockers.Length>0&&JsonSerializer.Serialize(changed.History[0].Pair,Fixture.Json)==original,"Draft changes invalidate current applicability but retain original exact submitted pair");
material=await f.Store.ReadMaterials(f.Id);await f.Store.SaveMaterials(f.Id,new(material.Plan.Revision,material.Plan.Rows,Complete:true,ChargeContractVersion:2,EvidenceContractVersion:1,PartReviewContractVersion:1),admin);var flagged=await f.Store.ReadEstimateSubmission(f.Id,admin);Check(flagged.Blockers.Any(b=>b.StartsWith("Find 3:"))&&!flagged.CanSubmit,"Completed estimate still blocks an unresolved proposed part; completion is not approval");
var parts=await f.Store.ReadMaterialPartRequests(f.Id,admin);await f.Store.CreateMaterialPartRequest(f.Id,new(parts.Token,Guid.NewGuid().ToString(),"INTERNAL_BOM_UPDATE",[0],"Fixture authorized estimate-only allowance",RoutingContractVersion:2),admin);var allowed=await f.Store.ReadEstimateSubmission(f.Id,admin);Check(allowed.CanSubmit&&allowed.Blockers.Length==0,"Existing valid authorized estimate-only allowance permits internal submission without changing approved BOM");
var aggregate=JsonSerializer.SerializeToElement(await f.Store.ReadRfqCommercialQueue(),Fixture.Json).GetProperty("parentGroups")[0];Check(aggregate.GetProperty("submittedLines").GetInt32()==2,"Stale line submission no longer counts as current in parent aggregate");
Check(f.SourcesUnchanged(),"Approved sources, parent identity and packages remain unchanged");
var output=CheckpointPaths.Results;await File.WriteAllTextAsync(Path.Combine(output,"BACKEND-RESULTS.json"),JsonSerializer.Serialize(new{passed=checks.Count,checks,actualBusinessWrites=0},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("TOTAL "+checks.Count);
